// Acceptance for re-cinq/HALEngine#93: afterModelResponse receives what every provider call in the turn reported, not the last round alone.
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';

// Fixed: nothing asserts on it, and new Date() would tie the run to the clock.
const SENT_AT = '2026-01-01T00:00:00.000Z';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

// What one provider call is told to do: ask for the `search` tool, or speak `text` and end the turn. `usage` is what its stop chunk reports.
interface ScriptedRound {
  toolCall?: boolean;
  text?: string;
  usage?: UsageMetadata;
}

// One sendMessage call per round, in order, so a test states each round's known token counts itself.
const scriptedTurn = (rounds: ScriptedRound[]): AIProvider => {
  let called = 0;

  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      const round = rounds[called++];

      if (round?.toolCall) {
        yield {type: 'tool_use', toolCall: {id: `call-${called}`, name: 'search', input: {q: 'weather'}}};
      }
      if (round?.text !== undefined) yield {type: 'text', text: round.text};

      const stopReason = round?.toolCall ? 'tool_use' : 'end_turn';
      yield round?.usage
        ? {type: 'stop', stopReason, usage: round.usage}
        : {type: 'stop', stopReason};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
