// Acceptance for re-cinq/HALEngine#93: the usage afterModelResponse receives covers every provider call in the turn, not the last round alone.
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';

// Fixed: nothing asserts on it, and new Date() would tie the run to the clock.
const SENT_AT = '2026-01-01T00:00:00.000Z';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

// What one provider call does: ask for the search tool, speak its closing text, and the usage its stop chunk reports.
interface ScriptedRound {
  toolCall?: boolean;
  text?: string;
  usage?: UsageMetadata;
}

// One sendMessage call per scripted round, in order, so each test states the token counts its rounds report.
const scriptedTurn = (rounds: ScriptedRound[]): AIProvider => {
  let called = 0;

  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      const round: ScriptedRound | undefined = rounds[called++];

      if (round?.toolCall) {
        yield {type: 'tool_use', toolCall: {id: `call-${called}`, name: 'search', input: {q: 'weather'}}};
      }
      if (round?.text !== undefined) yield {type: 'text', text: round.text};

      const stop: MessageChunk = round?.usage
        ? {type: 'stop', stopReason: round.toolCall ? 'tool_use' : 'end_turn', usage: round.usage}
        : {type: 'stop', stopReason: round?.toolCall ? 'tool_use' : 'end_turn'};
      yield stop;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

// The real registry executes the scripted tool call, so the rounds after the first are the orchestrator's own.
const registryWithSearch = (): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'search', description: 'returns a stored answer', inputSchema: {type: 'object'}},
    async () => ({result: 'the tool ran'})
  );
  return registry;
};

const sessionAsking = (question: string): ChatSession => ({
  sessionId: 'usage-turn',
  userId: 'audit-user',
  entries: [{role: 'user', content: question, timestamp: SENT_AT}],
});

// Drives one real turn through the orchestrator and returns what afterModelResponse was handed.
const turnUsage = async (rounds: ScriptedRound[]): Promise<(UsageMetadata | undefined)[]> => {
  const received: (UsageMetadata | undefined)[] = [];
  const hooks: OrchestratorHooks = {
    afterModelResponse: async (_session, _responseText, usage) => {
      received.push(usage);
    },
  };

  const orchestrator = createChatOrchestrator(scriptedTurn(rounds), promptBuilder, registryWithSearch(), {hooks});
  await orchestrator.processMessage(sessionAsking('what is the weather?'));

  return received;
};

describe('afterModelResponse usage across every tool round', () => {
  it('reports usage summed across every provider call of a tool turn', async () => {
    const received = await turnUsage([
      {toolCall: true, usage: {inputTokens: 1200, outputTokens: 300, totalTokens: 1500}},
      {text: 'the answer', usage: {inputTokens: 4800, outputTokens: 250, totalTokens: 5050}},
    ]);

    expect(received).toEqual([{inputTokens: 6000, outputTokens: 550, totalTokens: 6550}]);
  });

  it('still counts the rounds that reported when a round reports no usage', async () => {
    const received = await turnUsage([
      {toolCall: true, usage: {inputTokens: 700, outputTokens: 90, totalTokens: 790}},
      {toolCall: true},
      {text: 'the answer', usage: {inputTokens: 2100, outputTokens: 480, totalTokens: 2580}},
    ]);

    expect(received).toEqual([{inputTokens: 2800, outputTokens: 570, totalTokens: 3370}]);
  });

  it('reports no usage when no round in the turn reported any', async () => {
    const received = await turnUsage([{toolCall: true}, {text: 'the answer'}]);

    expect({calls: received.length, usage: received[0]}).toEqual({calls: 1, usage: undefined});
  });
});

